function toInputDate(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function todayInWib() {
  const dateParts = new Intl.DateTimeFormat("en-US", {
    timeZone: WIB_TIME_ZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(new Date());
  const part = (type) => dateParts.find((item) => item.type === type)?.value;
  return `${part("year")}-${part("month")}-${part("day")}`;
}

function addYearsClamped(value, years) {
  if (!value || !Number.isInteger(Number(years))) return "";
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(year + Number(years), month - 1, day);
  if (date.getMonth() !== month - 1) date.setDate(0);
  return toInputDate(date);
}

function addDays(value, days) {
  if (!value || !Number.isInteger(Number(days))) return "";
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  date.setUTCDate(date.getUTCDate() + Number(days));
  return date.toISOString().slice(0, 10);
}

function daysBetween(startDate, endDate) {
  if (!startDate || !endDate) return 0;
  const toUtc = (value) => {
    const [year, month, day] = value.split("-").map(Number);
    return Date.UTC(year, month - 1, day);
  };
  return Math.round((toUtc(endDate) - toUtc(startDate)) / 86_400_000);
}

function insuranceTerm(startDate, endDate) {
  const totalDays = daysBetween(startDate, endDate);
  if (totalDays <= 0) return { days: 0, label: "-", totalDays: 0, years: 0 };

  let years = Math.max(0, Number(endDate.slice(0, 4)) - Number(startDate.slice(0, 4)));
  while (years > 0 && addYearsClamped(startDate, years) > endDate) years -= 1;
  const anniversary = addYearsClamped(startDate, years);
  const days = daysBetween(anniversary, endDate);
  return { days, label: `${years} tahun, ${days} hari`, totalDays, years };
}

function formatRupiah(value) {
  return new Intl.NumberFormat("id-ID", {
    style: "currency",
    currency: "IDR",
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(Math.round(Number(value) || 0));
}

function formatNumber(value, maximumFractionDigits = 3) {
  return new Intl.NumberFormat("id-ID", { maximumFractionDigits }).format(Number(value) || 0);
}

function formatDate(value) {
  if (!value) return "-";
  const [year, month, day] = value.split("-").map(Number);
  return new Intl.DateTimeFormat("id-ID", { day: "2-digit", month: "long", year: "numeric" }).format(
    new Date(year, month - 1, day),
  );
}

function currencyDigits(value) {
  return String(value || "").replace(/\D/g, "");
}

function formattedCurrencyInput(value) {
  const digits = currencyDigits(value);
  return digits ? new Intl.NumberFormat("id-ID").format(Number(digits)) : "";
}

function baseRateFor(occupancyKey, constructionClass) {
  const occupancy = OCCUPANCIES[occupancyKey];
  if (!occupancy || !constructionClass) return { rate: 0, source: "Pilih okupasi dan kelas konstruksi." };
  if (constructionClass === "1") {
    return { rate: occupancy.annualRatePermille, source: "Tarif otomatis OJK untuk Konstruksi Kelas 1." };
  }
  const rate = occupancy.ojkRates?.[constructionClass]?.lower || 0;
  return {
    rate,
    source: `Tarif OJK batas bawah untuk Konstruksi Kelas ${constructionClass}.`,
  };
}

function extensionRateFor({ occupancyKey, extensions, floodLocation, earthquakeFloorCount, earthquakeLocation, riskAddress }) {
  const errors = [];
  const rows = [];
  const isDwelling2976 = isEarthquakeDwelling(occupancyKey);

  if (extensions.includes("banjir")) {
    if (!floodLocation) errors.push("Lokasi banjir wajib dipilih untuk menentukan tarif.");
    else rows.push({ label: "Banjir", rate: floodLocation === "jabodetabek" ? 0.5 : 0.45, source: "Tarif banjir OJK Zona 1" });
  }
  if (extensions.includes("gempa")) {
    if (!riskAddress.trim()) errors.push("Alamat risiko wajib diisi untuk menentukan zona gempa.");
    if (earthquakeLocation.status === "empty") errors.push("Kode pos alamat risiko wajib diisi untuk menentukan zona gempa.");
    if (earthquakeLocation.status === "incomplete") errors.push("Kode pos alamat risiko harus terdiri dari 5 angka.");
    if (earthquakeLocation.status === "not-found") errors.push("Kode pos alamat risiko tidak ditemukan dalam referensi wilayah.");
    if (earthquakeLocation.status === "ambiguous") errors.push("Pilih kota atau kabupaten untuk kode pos alamat risiko tersebut.");
    if (!isDwelling2976 && (!Number.isInteger(Number(earthquakeFloorCount)) || Number(earthquakeFloorCount) < 1)) errors.push("Jumlah lantai wajib diisi untuk okupasi selain Rumah Tinggal (2976).");
    if (earthquakeLocation.zone) {
      const { rate, floorBand } = earthquakeRateFor({ occupancyKey, floorCount: earthquakeFloorCount, zone: earthquakeLocation.zone });
      const floorDescription = floorBand === "le9" ? "1-9 lantai" : floorBand === "gt9" ? "lebih dari 9 lantai" : "Rumah Tinggal 2976";
      if (rate) rows.push({ label: "Gempa", rate, source: `Tarif gempa OJK Zona ${earthquakeLocation.zone}, ${floorDescription} (${earthquakeLocation.locationLabel})` });
    }
  }
  if (extensions.includes("rsmd")) rows.push({ label: "Kerusuhan", rate: 0.001, source: "Kerusuhan 0,001‰ per tahun" });
  if (extensions.includes("rsmdcc")) rows.push({ label: "Kerusuhan dan Huru-Hara", rate: 0.001, source: "Kerusuhan dan Huru-Hara 0,001‰ per tahun" });

  return { rows, errors, rate: rows.reduce((total, item) => total + item.rate, 0) };
}

