function ConstructionClassSelect({ value, onChange }) {
  const [isOpen, setIsOpen] = useState(false);
  const selectedLabel = value ? `Kelas ${value}` : "Pilih kelas konstruksi";

  return (
    <div className="construction-select" onBlur={(event) => { if (!event.currentTarget.contains(event.relatedTarget)) setIsOpen(false); }}>
      <button className="construction-select__trigger" type="button" aria-labelledby="constructionClassLabel" aria-haspopup="listbox" aria-expanded={isOpen} onClick={() => setIsOpen((current) => !current)} onKeyDown={(event) => { if (event.key === "Escape") setIsOpen(false); }}>
        <span>{selectedLabel}</span><ChevronDown size={18} aria-hidden="true" />
      </button>
      {isOpen ? <div className="construction-select__menu" role="listbox" aria-label="Kelas Konstruksi">
        {Object.entries(CONSTRUCTION_CLASS_DESCRIPTIONS).map(([key, description]) => (
          <button className={`construction-select__option ${value === key ? "is-selected" : ""}`} type="button" role="option" aria-selected={value === key} key={key} onClick={() => { onChange(key); setIsOpen(false); }}>
            <span><strong>Kelas {key}</strong><small>{description}</small></span>{value === key ? <Check size={18} aria-hidden="true" /> : null}
          </button>
        ))}
      </div> : null}
    </div>
  );
}

