export function App() {
  const [form, setForm] = useState(initialForm);
  const [errors, setErrors] = useState([]);
  const [calculation, setCalculation] = useState(null);
  const [isStale, setIsStale] = useState(false);
  const [isPreparingPdf, setIsPreparingPdf] = useState(false);
  const [isMapPickerOpen, setIsMapPickerOpen] = useState(false);
  const quotationPdfCache = useRef({ fingerprint: "", file: null });

  const buildingValue = Number(currencyDigits(form.buildingValue)) || 0;
  const inventoryValue = Number(currencyDigits(form.inventoryValue)) || 0;
  const tsi = buildingValue + inventoryValue;
  const occupancy = OCCUPANCIES[form.occupancy];
  const baseRate = useMemo(
    () => baseRateFor(form.occupancy, form.constructionClass),
    [form.constructionClass, form.occupancy],
  );
  const earthquakeLocation = useMemo(
    () => resolveEarthquakePostalCode(form.earthquakePostalCode, form.earthquakeRegionKey),
    [form.earthquakePostalCode, form.earthquakeRegionKey],
  );
  const extensionRate = useMemo(
    () => extensionRateFor({ ...form, occupancyKey: form.occupancy, earthquakeLocation }),
    [earthquakeLocation, form],
  );
  const periodEnd = form.endDate;
  const term = insuranceTerm(form.startDate, form.endDate);
  const premiumTermYears = term.years + term.days / 365;
  const minEndDate = addDays(form.startDate, MIN_POLICY_DAYS);
  const maxEndDate = addDays(form.startDate, MAX_POLICY_DAYS);
  const hasFlood = form.extensions.includes("banjir");
  const hasEarthquake = form.extensions.includes("gempa");
  const hasRsmd = form.extensions.includes("rsmd");
  const hasRsmdcc = form.extensions.includes("rsmdcc");
  const isDwelling = Boolean(occupancy?.residential);
  const isEarthquakeDwelling2976 = isEarthquakeDwelling(form.occupancy);

  const update = (key, value) => {
    setForm((current) => {
      const next = { ...current, [key]: value };
      if (key === "startDate" && value) {
        const minimumEndDate = addDays(value, MIN_POLICY_DAYS);
        const maximumEndDate = addDays(value, MAX_POLICY_DAYS);
        if (!current.endDate || current.endDate < minimumEndDate) next.endDate = addYearsClamped(value, 1);
        else if (current.endDate > maximumEndDate) next.endDate = maximumEndDate;
      }
      if (key === "endDate" && value && current.startDate) {
        const minimumEndDate = addDays(current.startDate, MIN_POLICY_DAYS);
        const maximumEndDate = addDays(current.startDate, MAX_POLICY_DAYS);
        if (value < minimumEndDate) next.endDate = minimumEndDate;
        else if (value > maximumEndDate) next.endDate = maximumEndDate;
      }
      if (key === "extensionsEnabled" && !value) {
        next.extensions = [];
        next.floodLocation = "";
        next.earthquakeFloorCount = "";
        next.earthquakePostalCode = "";
        next.earthquakeRegionKey = "";
      }
      if (key === "earthquakePostalCode") next.earthquakeRegionKey = "";
      return next;
    });
    setErrors([]);
    if (calculation) setIsStale(true);
  };

  const toggleExtension = (key) => {
    update(
      "extensions",
      form.extensions.includes(key) ? form.extensions.filter((item) => item !== key) : [...form.extensions, key],
    );
  };

  const reset = () => {
    setForm(initialForm());
    setErrors([]);
    setCalculation(null);
    setIsStale(false);
  };

  const calculate = (event) => {
    event.preventDefault();
    const nextErrors = [];
    if (!form.insuredName.trim()) nextErrors.push("Nama tertanggung atau debitur wajib diisi.");
    if (!form.riskAddress.trim()) nextErrors.push("Alamat risiko wajib diisi.");
    if (!form.startDate) nextErrors.push("Tanggal mulai pertanggungan wajib diisi.");
    if (!form.endDate) nextErrors.push("Tanggal akhir pertanggungan wajib diisi.");
    if (!occupancy) nextErrors.push("Okupasi atau penggunaan bangunan wajib dipilih.");
    if (!form.constructionClass) nextErrors.push("Kelas konstruksi wajib dipilih.");
    if (term.totalDays < MIN_POLICY_DAYS) nextErrors.push("Jangka waktu pertanggungan minimal 364 hari.");
    if (term.totalDays > MAX_POLICY_DAYS) nextErrors.push("Jangka waktu pertanggungan maksimal 10.958 hari.");
    if (buildingValue <= 0) nextErrors.push("Harga pertanggungan bangunan wajib diisi.");
    if (tsi <= 0) nextErrors.push("Nilai pertanggungan harus lebih dari Rp0.");
    if (tsi > MAX_TSI) nextErrors.push("Total harga pertanggungan melebihi batas maksimum Rp10 miliar.");
    if (!baseRate.rate) nextErrors.push("Tarif jaminan utama belum dapat ditentukan.");
    nextErrors.push(...extensionRate.errors);

    if (nextErrors.length) {
      setErrors(nextErrors);
      setCalculation(null);
      setIsStale(false);
      return;
    }

    const totalAnnualRate = baseRate.rate + extensionRate.rate;
    const annualPremium = tsi * (totalAnnualRate / 1000);
    const premium = annualPremium * premiumTermYears;
    const totalPayable = premium + POLICY_FEE + STAMP_DUTY;
    setErrors([]);
    setIsStale(false);
    setCalculation({
      totalAnnualRate,
      annualPremium,
      premium,
      totalPayable,
      periodEnd,
      selectedExtensionLabels: extensionRate.rows.map((row) => row.label),
      ownRisk: occupancy.residential
        ? "Nihil"
        : `5% dari nilai klaim atau 0,1% dari TSI; minimum berdasarkan TSI ${formatRupiah(tsi * 0.001)}.`,
    });
  };

  const sideResult = calculation && !isStale ? calculation : null;
  const policyPeriod = `${formatDate(form.startDate)} s.d. ${formatDate(periodEnd)}`;
  const offerDate = todayInWib();
  const baseCoveragePremium = tsi * (baseRate.rate / 1000) * premiumTermYears;
  const quotationExtensions = extensionRate.rows.map((row) => ({
    ...row,
    Icon: EXTENSION_ICON_BY_LABEL[row.label] || Flame,
    premium: tsi * (row.rate / 1000) * premiumTermYears,
  }));

  const createQuotationPdf = async () => {
    const pdf = new jsPDF({ orientation: "p", unit: "mm", format: "a4", compress: true });
    const navy = [18, 61, 99];
    const blue = [28, 79, 119];
    const paleBlue = [232, 242, 248];
    const lineColor = [192, 207, 219];
    const textColor = [25, 36, 46];
    const left = 15;
    const right = 195;
    const contentWidth = right - left;
    const bottom = 260;

    const clean = (value) => String(value ?? "-")
      .replace(/‰/g, " per mil")
      .replace(/[–—]/g, "-")
      .replace(/\u00a0/g, " ");

    const setText = (size = 8.5, style = "normal", color = textColor) => {
      pdf.setFont("helvetica", style);
      pdf.setFontSize(size);
      pdf.setTextColor(...color);
    };

    const writeWrapped = (text, x, y, width, { size = 8.5, style = "normal", color = textColor, lineHeight = 4.2, align = "left" } = {}) => {
      setText(size, style, color);
      const lines = pdf.splitTextToSize(clean(text), width);
      pdf.text(lines, x, y, { align, lineHeightFactor: lineHeight / (size * 0.3528) });
      return y + lines.length * lineHeight;
    };

    const drawSectionTitle = (title, y) => {
      setText(9, "bold", navy);
      pdf.text(clean(title), left, y);
      pdf.setDrawColor(...blue);
      pdf.setLineWidth(0.35);
      pdf.line(left, y + 2.2, right, y + 2.2);
      return y + 7;
    };

    const drawLetterhead = () => {
      try {
        pdf.addImage(JASINDO_OFFICIAL_HEADER_LOGO, "PNG", 152, 7, 43, 30.4, undefined, "FAST");
      } catch {
        setText(10.5, "bold", navy);
        pdf.text("ASURANSI JASINDO", right, 17, { align: "right" });
      }

      setText(7.1, "bold", [0, 0, 0]);
      pdf.text("PT ASURANSI JASA INDONESIA", 105, 271.5, { align: "center" });
      setText(6.8, "bold", [0, 0, 0]);
      pdf.text(
        "Head Office: Graha Jasindo Jl. Menteng Raya No. 21 Jakarta Pusat, Daerah Khusus Ibukota Jakarta 10340. Indonesia",
        105,
        275.2,
        { align: "center" },
      );
      pdf.text("Ph. 021-3924737, 021-3924748 | E. Jasindo@asuransijasindo.co.id", 105, 278.9, { align: "center" });
      setText(7, "normal", [0, 0, 0]);
    };

    const drawInfoRows = (rows, startY) => {
      let y = startY;
      const labelWidth = 63;
      for (const [label, value] of rows) {
        const valueLines = pdf.splitTextToSize(clean(value || "-"), contentWidth - labelWidth - 8);
        const rowHeight = Math.max(7.2, valueLines.length * 4.1 + 2.6);
        setText(8.2, "normal", [53, 77, 98]);
        pdf.text(clean(label), left, y + 4.7);
        pdf.text(":", left + labelWidth - 4, y + 4.7);
        setText(8.2, "bold", textColor);
        pdf.text(valueLines, left + labelWidth, y + 4.7, { lineHeightFactor: 1.42 });
        pdf.setDrawColor(...lineColor);
        pdf.setLineWidth(0.2);
        pdf.line(left, y + rowHeight, right, y + rowHeight);
        y += rowHeight;
      }
      return y;
    };

    const premiumRows = [
      ["Jaminan Kebakaran", `${formatNumber(baseRate.rate)} per mil per tahun`, formatRupiah(baseCoveragePremium), "normal"],
      ...quotationExtensions.map(({ label, rate, premium }) => [`Perluasan ${label}`, `${formatNumber(rate)} per mil per tahun`, formatRupiah(premium), "normal"]),
      [`Premi untuk ${term.label}`, "", formatRupiah(sideResult.premium), "subtotal"],
      ["Biaya Polis", "", formatRupiah(POLICY_FEE), "normal"],
      ["Biaya Materai", "", formatRupiah(STAMP_DUTY), "normal"],
      ["TOTAL PREMI", "", formatRupiah(sideResult.totalPayable), "total"],
    ];

    const drawPremiumTable = (startY) => {
      let y = startY;
      const col1 = left;
      const col2 = 107;
      const col3 = 151;
      pdf.setFillColor(...navy);
      pdf.rect(left, y, contentWidth, 8, "F");
      setText(7.8, "bold", [255, 255, 255]);
      pdf.text("Jaminan", col1 + 2.5, y + 5.3);
      pdf.text("Tarif", col2 + 2.5, y + 5.3);
      pdf.text("Premi", right - 2.5, y + 5.3, { align: "right" });
      y += 8;

      for (const [label, rate, premium, kind] of premiumRows) {
        const rowHeight = 7.2;
        if (kind === "total") {
          pdf.setFillColor(...paleBlue);
          pdf.rect(left, y, contentWidth, rowHeight, "F");
        }
        pdf.setDrawColor(...lineColor);
        pdf.setLineWidth(kind === "total" ? 0.45 : 0.2);
        pdf.line(left, y + rowHeight, right, y + rowHeight);
        setText(kind === "total" ? 8.5 : 7.8, kind === "normal" ? "normal" : "bold", kind === "total" ? navy : textColor);
        pdf.text(clean(label), col1 + 2.5, y + 4.9);
        if (rate) {
          setText(7.4, "normal", [60, 84, 103]);
          pdf.text(clean(rate), col2 + 2.5, y + 4.9);
        }
        setText(kind === "total" ? 8.5 : 7.8, kind === "normal" ? "normal" : "bold", kind === "total" ? navy : textColor);
        pdf.text(clean(premium), right - 2.5, y + 4.9, { align: "right" });
        y += rowHeight;
      }
      pdf.setDrawColor(...lineColor);
      pdf.rect(left, startY, contentWidth, y - startY);
      return y;
    };

    const addTermsPage = (continuation = false) => {
      pdf.addPage();
      drawLetterhead();
      let y = 43;
      y = drawSectionTitle(continuation ? "SYARAT DAN KETENTUAN (LANJUTAN)" : "SYARAT DAN KETENTUAN", y);
      return y;
    };

    let termsY;
    const ensureTermsSpace = (height) => {
      if (termsY + height <= bottom) return;
      termsY = addTermsPage(true);
    };

    const drawTermsHeading = (heading) => {
      ensureTermsSpace(11);
      setText(8.3, "bold", navy);
      pdf.text(clean(heading), left, termsY + 2.5);
      termsY += 7;
    };

    const drawTermBullets = (items) => {
      for (const item of items) {
        const lines = pdf.splitTextToSize(clean(item), contentWidth - 8);
        const height = lines.length * 3.9 + 2;
        ensureTermsSpace(height);
        setText(8, "normal", textColor);
        pdf.circle(left + 1.2, termsY + 1.1, 0.45, "F");
        pdf.text(lines, left + 5, termsY + 2, { lineHeightFactor: 1.38 });
        termsY += height;
      }
    };

    drawLetterhead();
    setText(7.5, "normal", textColor);
    pdf.text(`Jakarta, ${formatDate(offerDate)}`, right, 42, { align: "right" });

    setText(8, "normal", textColor);
    pdf.text("Kepada Yth.", left, 54);
    setText(8.5, "bold", textColor);
    pdf.text(clean(form.insuredName), left, 59);
    setText(8, "normal", textColor);
    pdf.text("di tempat", left, 64);
    pdf.text("Dengan hormat,", left, 76);

    const subject = "PERIHAL: PENAWARAN ASURANSI KEBAKARAN";
    setText(9, "bold", textColor);
    pdf.text(subject, left, 87);
    pdf.setDrawColor(...textColor);
    pdf.setLineWidth(0.25);
    pdf.line(left, 88.2, left + pdf.getTextWidth(subject), 88.2);

    let y = writeWrapped(
      "Terima kasih atas kepercayaan Bapak/Ibu kepada PT Asuransi Jasa Indonesia. Bersama ini kami sampaikan penawaran Asuransi Kebakaran KPR Danantara dengan rincian sebagai berikut:",
      left,
      98,
      contentWidth,
      { size: 8, lineHeight: 4 },
    ) + 3;

    y = drawSectionTitle("RINCIAN PERTANGGUNGAN", y);
    y = drawInfoRows([
      ["Tertanggung / Debitur", form.insuredName],
      ["Alamat Risiko", form.riskAddress],
      ["Objek Pertanggungan / Okupasi", occupancy?.label],
      ["Kelas Konstruksi", `Kelas ${form.constructionClass}`],
      ["Periode Pertanggungan", policyPeriod],
      ["Harga Pertanggungan", formatRupiah(tsi)],
      ["Dasar Cakupan", "Polis Standar Asuransi Kebakaran Indonesia"],
    ], y);

    y = drawSectionTitle("JAMINAN DAN PERHITUNGAN PREMI", y + 7);
    drawPremiumTable(y);

    termsY = addTermsPage(false);
    drawTermsHeading("Wording Polis Standar Asuransi Kebakaran Indonesia");
    drawTermsHeading("Klausul");
    drawTermBullets([
      "Klausul Penyakit Menular (LMA 5393).",
      "Klausul Pembayaran Premi 30 hari.",
      "Klausul Ketentuan Khusus Mengenai Kewajiban Tertanggung Menyampaikan Keterangan, Informasi Dan Data (Fakta Material) Dan Konsekuensi Pelanggarannya.",
      ...(term.totalDays > 366 ? ["Klausul Polis Lebih dari Satu Tahun."] : []),
      "Klausul Bank.",
      "Klausul Pemberitahuan Kerugian (30 hari).",
      "Klausul Definisi Surat Permohonan Asuransi Umum (SPAU).",
      ...(hasFlood ? ["Endorsemen Banjir, Angin Topan, Badai Dan Kerusakan Akibat Air (Kode: 4.3 A)."] : []),
      ...(hasRsmd ? ["Endorsemen Kerusuhan, Pemogokan, Dan Perbuatan Jahat (Kode: 4.1A / 2007)."] : []),
      ...(hasRsmdcc ? ["Endorsemen Kerusuhan, Pemogokan, Perbuatan Jahat, Dan Huru-Hara (Kode: 4.1B / 2007)."] : []),
    ]);

    drawTermsHeading("Warranty dan Ketentuan Khusus");
    drawTermBullets([
      "Tidak terjadi klaim sampai dengan Tanggal Pengikatan/Mulai Berlaku (mana yang paling akhir); jika terjadi klaim, maka ketentuan akan direvisi.",
      "Tertanggung wajib menjaga kebersihan area di lokasi pertanggungan selama masa periode pertanggungan.",
      "Objek pertanggungan tidak boleh dibiarkan kosong, tidak aktif, atau tidak diawasi selama masa pertanggungan. Bangunan/aset harus tetap digunakan dan tidak dalam kondisi terbengkalai (No Silent Risk).",
      "Objek pertanggungan agar dirinci per lokasi, tipe, jenis, dan unit harga ditegaskan dalam polis.",
      "Tidak ada perubahan okupasi selama periode pertanggungan.",
    ]);

    drawTermsHeading("Risiko Sendiri");
    drawTermBullets([
      `Kebakaran: ${isDwelling ? "Nil." : "5% dari nilai kerugian yang disetujui atau 0,1% dari total nilai pertanggungan untuk setiap risiko dan setiap lokasi, mana yang lebih besar."}`,
      ...(hasFlood ? ["Banjir: 10% dari jumlah ganti rugi yang disetujui."] : []),
      ...(hasEarthquake ? ["Gempa: 2,5% dari Harga Pertanggungan Keseluruhan."] : []),
      ...(hasRsmd || hasRsmdcc ? ["Kerusuhan / Kerusuhan dan Huru-Hara: 5% dari jumlah ganti rugi yang disetujui, minimum Rp5.000.000 setiap kejadian."] : []),
    ]);

    const disclaimerLines = pdf.splitTextToSize(clean(UNDERWRITING_DISCLAIMER), contentWidth);
    const disclaimerHeight = disclaimerLines.length * 4.2;
    ensureTermsSpace(disclaimerHeight + 36);
    termsY += 4;
    setText(8.2, "normal", textColor);
    pdf.text(disclaimerLines, left, termsY + 2, { lineHeightFactor: 1.45 });
    termsY += disclaimerHeight + 4;
    setText(8.5, "normal", textColor);
    pdf.text("Hormat kami,", left, termsY + 5);
    setText(8.8, "bold", textColor);
    pdf.text("PT Asuransi Jasa Indonesia", left, termsY + 24);

    const safeFilenamePart = (value, fallback) => String(value || fallback)
      .replace(/[<>:"/\\|?*\u0000-\u001f]/g, " ")
      .replace(/\s+/g, " ")
      .replace(/[. ]+$/g, "")
      .trim() || fallback;
    const insuredName = safeFilenamePart(form.insuredName, "Tertanggung");
    return new File([pdf.output("blob")], `Penawaran ${insuredName}.pdf`, { type: "application/pdf" });
  };

  const getQuotationPdf = async () => {
    const fingerprint = JSON.stringify({ form, calculation: sideResult });
    if (quotationPdfCache.current.fingerprint === fingerprint && quotationPdfCache.current.file) {
      return quotationPdfCache.current.file;
    }

    const file = await createQuotationPdf();
    quotationPdfCache.current = { fingerprint, file };
    return file;
  };

  const saveQuotationPdf = async () => {
    setIsPreparingPdf(true);
    try {
      const pdfFile = await getQuotationPdf();
      if (!pdfFile) return;
      const downloadUrl = URL.createObjectURL(pdfFile);
      const download = document.createElement("a");
      download.href = downloadUrl;
      download.download = pdfFile.name;
      download.click();
      window.setTimeout(() => URL.revokeObjectURL(downloadUrl), 1_000);
    } finally {
      setIsPreparingPdf(false);
    }
  };

  const shareQuotationPdf = async () => {
    setIsPreparingPdf(true);
    try {
      const pdfFile = await getQuotationPdf();
      if (!pdfFile) return;
      const shareData = {
        files: [pdfFile],
        title: "Penawaran Asuransi Kebakaran KPR Danantara",
        text: `Penawaran Asuransi Kebakaran KPR Danantara untuk ${form.insuredName}.`,
      };

      const canSharePdfFile = typeof navigator.share === "function"
        && (typeof navigator.canShare !== "function" || navigator.canShare({ files: [pdfFile] }));

      if (canSharePdfFile) {
        try {
          await navigator.share(shareData);
          return;
        } catch (error) {
          if (error?.name === "AbortError") return;
        }
      }

      const downloadUrl = URL.createObjectURL(pdfFile);
      const download = document.createElement("a");
      download.href = downloadUrl;
      download.download = pdfFile.name;
      download.click();
      window.setTimeout(() => URL.revokeObjectURL(downloadUrl), 1_000);
      window.alert("Perangkat ini belum mendukung pengiriman lampiran PDF langsung. File PDF yang sama telah diunduh dan siap dikirim sebagai lampiran.");
    } finally {
      setIsPreparingPdf(false);
    }
  };


  return (
    <div className="app-shell">
      <header className="site-header">
        <div className="brand-lockup" aria-label="Danantara Indonesia">
          <img src="/assets/danantara.png" alt="Danantara Indonesia" />
        </div>
        <img className="header-jasindo" src="/assets/jasindo-white.png" alt="Asuransi Jasindo" />
      </header>

      <main id="kalkulator" className="calculator-page">
        <div className="page-heading">
          <div>
            <p className="eyebrow">SIMULASI PREMI PROPERTI</p>
            <h1>Kalkulator Premi Kebakaran KPR Danantara</h1>
          </div>
          <div className="heading-date"><CalendarDays size={18} aria-hidden="true" />{formatDate(form.startDate)}</div>
        </div>

        <div className="calculator-layout">
          <form className="calculator-form" onSubmit={calculate} noValidate>
            {errors.length ? (
              <div className="error-box" role="alert">
                <CircleAlert size={20} aria-hidden="true" />
                <div>{errors.map((error) => <p key={error}>{error}</p>)}</div>
              </div>
            ) : null}

            <section className="form-section">
              <SectionTitle step="1">Data Penutupan</SectionTitle>
              <div className="form-grid form-grid--two">
                <label className="field field--full" htmlFor="insuredName"><span>Tertanggung / Debitur <b>*</b></span><input id="insuredName" placeholder="Nama tertanggung" value={form.insuredName} onChange={(event) => update("insuredName", event.target.value)} /></label>
                <div className="field field--full"><label htmlFor="riskAddress">Alamat Risiko <b>*</b></label><div className="risk-address-control"><input id="riskAddress" placeholder="Alamat objek pertanggungan" value={form.riskAddress} onChange={(event) => update("riskAddress", event.target.value)} /><button className="map-picker-trigger" type="button" onClick={() => setIsMapPickerOpen(true)}><MapPin size={17} aria-hidden="true" />Pilih dari Map</button></div></div>
                <label className="field field--third" htmlFor="startDate"><span>Tanggal Mulai Pertanggungan <b>*</b></span><input id="startDate" type="date" value={form.startDate} onChange={(event) => update("startDate", event.target.value)} /></label>
                <label className="field field--third" htmlFor="endDate"><span>Tanggal Akhir Pertanggungan <b>*</b></span><input id="endDate" type="date" min={minEndDate} max={maxEndDate} value={form.endDate} onChange={(event) => update("endDate", event.target.value)} /></label>
                <label className="field field--third" htmlFor="years"><span>Jangka Waktu Asuransi <small>(otomatis)</small></span><input id="years" value={term.label} readOnly /></label>
              </div>
            </section>

            <section className="form-section">
              <SectionTitle step="2">Data Objek Pertanggungan</SectionTitle>
              <div className="form-grid form-grid--two">
                <label className="field" htmlFor="occupancy"><span>Okupasi (Penggunaan Bangunan) <b>*</b></span><select id="occupancy" value={form.occupancy} onChange={(event) => update("occupancy", event.target.value)}><option value="">Pilih okupasi</option>{Object.entries(OCCUPANCIES).map(([key, item]) => <option key={key} value={key}>{item.label}</option>)}</select></label>
                <div className="field"><span id="constructionClassLabel">Kelas Konstruksi <b>*</b></span><ConstructionClassSelect value={form.constructionClass} onChange={(value) => update("constructionClass", value)} /></div>
                <MoneyInput id="buildingValue" label="Harga Pertanggungan Bangunan" required value={form.buildingValue} onChange={(value) => update("buildingValue", value)} />
                <MoneyInput id="inventoryValue" label="Harga Pertanggungan Inventaris" value={form.inventoryValue} onChange={(value) => update("inventoryValue", value)} />
              </div>
              <div className={`rate-message ${baseRate.rate ? "rate-message--ready" : ""}`}><Info size={17} aria-hidden="true" /><span><b>Tarif:</b>{baseRate.rate ? ` ${formatNumber(baseRate.rate)}‰ per tahun.` : " Pilih okupasi dan kelas konstruksi."}</span></div>
              <div className={`tsi-banner ${tsi > MAX_TSI ? "tsi-banner--danger" : ""}`}><span>Total Harga Pertanggungan</span><strong>{formatRupiah(tsi)}</strong></div>
            </section>

            <section className="form-section">
              <div className="extension-heading-row">
                <SectionTitle step="3">Perluasan Jaminan <em>(Opsional)</em></SectionTitle>
                <div className="extension-toggle" role="radiogroup" aria-label="Ada perluasan jaminan?">
                  <span>Ada perluasan jaminan?</span>
                  <label><input type="radio" name="extensionsEnabled" checked={form.extensionsEnabled} onChange={() => update("extensionsEnabled", true)} />Ya</label>
                  <label><input type="radio" name="extensionsEnabled" checked={!form.extensionsEnabled} onChange={() => update("extensionsEnabled", false)} />Tidak</label>
                </div>
              </div>
              {form.extensionsEnabled ? <>
                <p className="section-help">Pilih perluasan jaminan yang diperlukan.</p>
                <div className="extension-grid">
                  {EXTENSION_OPTIONS.map(({ key, label, Icon }) => (
                    <label className={`extension-card ${form.extensions.includes(key) ? "is-selected" : ""}`} key={key}>
                      <input type="checkbox" checked={form.extensions.includes(key)} onChange={() => toggleExtension(key)} />
                      <Icon size={21} aria-hidden="true" />
                      <span>{label}</span>
                    </label>
                  ))}
                </div>
                {hasFlood || hasEarthquake ? (
                  <div className="extension-details">
                    {hasFlood ? <label className="field" htmlFor="floodLocation"><span>Lokasi Banjir <b>*</b></span><select id="floodLocation" value={form.floodLocation} onChange={(event) => update("floodLocation", event.target.value)}><option value="">Pilih lokasi banjir</option><option value="jabodetabek">Jakarta, Banten, Jawa Barat</option><option value="other">Selain Jakarta, Banten, Jawa Barat</option></select></label> : null}
                    {hasEarthquake && !isEarthquakeDwelling2976 ? <label className="field" htmlFor="earthquakeFloorCount"><span>Jumlah Lantai Bangunan <b>*</b></span><select id="earthquakeFloorCount" value={form.earthquakeFloorCount} onChange={(event) => update("earthquakeFloorCount", event.target.value)}><option value="">Pilih jumlah lantai bangunan</option><option value="9">Sampai dengan 9 lantai</option><option value="10">Lebih dari 9 lantai</option></select></label> : null}
                    {hasEarthquake ? <label className="field" htmlFor="earthquakePostalCode"><span>Kode Pos Alamat Risiko <b>*</b></span><input id="earthquakePostalCode" inputMode="numeric" maxLength={5} pattern="[0-9]{5}" placeholder="Contoh: 10310" value={form.earthquakePostalCode} onChange={(event) => update("earthquakePostalCode", event.target.value.replace(/\D/g, "").slice(0, 5))} />{earthquakeLocation.status === "resolved" ? <small className="postal-zone-status postal-zone-status--ready">{earthquakeLocation.locationLabel} - Zona Gempa {earthquakeLocation.zone}</small> : null}{earthquakeLocation.status === "incomplete" ? <small className="postal-zone-status">Masukkan 5 angka kode pos.</small> : null}{earthquakeLocation.status === "not-found" ? <small className="postal-zone-status postal-zone-status--error">Kode pos tidak ditemukan.</small> : null}{earthquakeLocation.status === "ambiguous" ? <small className="postal-zone-status">Kode pos mencakup lebih dari satu wilayah. Pilih wilayah yang sesuai.</small> : null}</label> : null}
                    {hasEarthquake && earthquakeLocation.status === "ambiguous" ? <label className="field" htmlFor="earthquakeRegionKey"><span>Kota / Kabupaten <b>*</b></span><select id="earthquakeRegionKey" value={form.earthquakeRegionKey} onChange={(event) => update("earthquakeRegionKey", event.target.value)}><option value="">Pilih wilayah alamat risiko</option>{earthquakeLocation.candidates.map((candidate) => <option value={candidate.key} key={candidate.key}>{formatAdministrativeRegion(candidate.region)}, {candidate.province}</option>)}</select></label> : null}
                  </div>
                ) : null}
                <div className={`rate-message ${form.extensions.length && !extensionRate.errors.length ? "rate-message--ready" : ""}`}><Info size={17} aria-hidden="true" /><span><b>Tarif Perluasan:</b> {form.extensions.length ? extensionRate.errors[0] || `${formatNumber(extensionRate.rate)}‰ per tahun (${extensionRate.rows.map((row) => row.label).join(", ")}).` : "Tidak ada perluasan dipilih."}</span></div>
              </> : null}
            </section>

            <div className="form-actions">
              <button className="button button--secondary" type="button" onClick={reset}><RefreshCcw size={17} aria-hidden="true" />Reset</button>
              <button className="button button--primary" type="submit"><Calculator size={18} aria-hidden="true" />Hitung Premi</button>
            </div>
          </form>

          <aside className="summary-aside" aria-label="Ringkasan hasil perhitungan">
            <section className={`result-card ${sideResult ? "has-result" : ""}`}>
              <div className="result-card__header"><Calculator size={22} aria-hidden="true" /><div><h2>Ringkasan Hasil</h2><p>{sideResult ? "Estimasi premi yang perlu disiapkan" : "Hasil akan tampil setelah dihitung"}</p></div></div>
              {sideResult ? <>
                <SummaryLine label="Total Harga Pertanggungan" value={formatRupiah(tsi)} />
                <SummaryLine label="Tarif dasar" value={`${formatNumber(baseRate.rate)}‰`} />
                <SummaryLine label="Tarif perluasan" value={`${formatNumber(extensionRate.rate)}‰`} />
                <SummaryLine label="Premi tahunan" value={formatRupiah(sideResult.annualPremium)} />
                <SummaryLine label="Biaya polis" value={formatRupiah(POLICY_FEE)} />
                <SummaryLine label="Biaya materai" value={formatRupiah(STAMP_DUTY)} />
                <SummaryLine total label="Total premi" value={formatRupiah(sideResult.totalPayable)} />
              </> : <div className="result-card__empty"><Calculator size={30} aria-hidden="true" /><span>Masukkan data objek pertanggungan dan tekan <b>Hitung Premi</b>.</span></div>}
              <div className="quotation-actions">
                <button className="print-button" type="button" disabled={!sideResult || isPreparingPdf} onClick={saveQuotationPdf}><Printer size={16} aria-hidden="true" />{isPreparingPdf ? "Menyiapkan PDF..." : "Simpan PDF Penawaran"}</button>
                <button className="send-button" type="button" disabled={!sideResult || isPreparingPdf} onClick={shareQuotationPdf}><Send size={16} aria-hidden="true" />{isPreparingPdf ? "Menyiapkan PDF..." : "Kirim PDF Penawaran"}</button>
              </div>
            </section>
          </aside>
        </div>

        {sideResult ? (
          <article className="quotation-document quotation-letter" aria-label="Surat penawaran asuransi">
            <div className="quotation-letter__pdf-page">
              <header className="quotation-letter__letterhead">
                <div className="quotation-letter__identity"><span>PT ASURANSI JASA INDONESIA</span><small>Penawaran Asuransi Kebakaran KPR Danantara</small></div>
                <img src={JASINDO_COLOR_LOGO} alt="Asuransi Jasindo" />
              </header>
              <div className="quotation-letter__reference"><span>Jakarta, {formatDate(offerDate)}</span></div>

              <div className="quotation-letter__recipient"><span>Kepada Yth.</span><strong>{form.insuredName}</strong><span>di tempat</span></div>

              <p>Dengan hormat,</p>
              <h2>PERIHAL: PENAWARAN ASURANSI KEBAKARAN</h2>
              <p>Terima kasih atas kepercayaan Bapak/Ibu kepada PT Asuransi Jasa Indonesia. Bersama ini kami sampaikan penawaran Asuransi Kebakaran KPR Danantara dengan rincian sebagai berikut:</p>

              <section className="quotation-letter__section">
              <h3>RINCIAN PERTANGGUNGAN</h3>
              <dl className="quotation-letter__details">
                <div><dt>Tertanggung / Debitur</dt><dd>{form.insuredName}</dd></div>
                <div><dt>Alamat Risiko</dt><dd>{form.riskAddress}</dd></div>
                <div><dt>Objek Pertanggungan / Okupasi</dt><dd>{occupancy?.label}</dd></div>
                <div><dt>Kelas Konstruksi</dt><dd>Kelas {form.constructionClass}</dd></div>
                <div><dt>Periode Pertanggungan</dt><dd>{policyPeriod}</dd></div>
                <div><dt>Harga Pertanggungan</dt><dd>{formatRupiah(tsi)}</dd></div>
                <div><dt>Dasar Cakupan</dt><dd>Polis Standar Asuransi Kebakaran Indonesia</dd></div>
              </dl>
            </section>

              <section className="quotation-letter__section">
              <h3>JAMINAN DAN PERHITUNGAN PREMI</h3>
              <div className="quotation-letter__table-wrap">
                <table className="quotation-letter__premium-table">
                  <thead><tr><th>Jaminan</th><th>Tarif</th><th>Premi</th></tr></thead>
                  <tbody>
                    <tr><td>Jaminan Kebakaran</td><td>{formatNumber(baseRate.rate)}‰ per tahun</td><td>{formatRupiah(baseCoveragePremium)}</td></tr>
                    {quotationExtensions.map(({ label, rate, premium }) => <tr key={label}><td>Perluasan {label}</td><td>{formatNumber(rate)}‰ per tahun</td><td>{formatRupiah(premium)}</td></tr>)}
                    <tr className="quotation-letter__subtotal"><td colSpan="2">Premi untuk {term.label}</td><td>{formatRupiah(sideResult.premium)}</td></tr>
                    <tr><td colSpan="2">Biaya Polis</td><td>{formatRupiah(POLICY_FEE)}</td></tr>
                    <tr><td colSpan="2">Biaya Materai</td><td>{formatRupiah(STAMP_DUTY)}</td></tr>
                    <tr className="quotation-letter__total"><td colSpan="2">TOTAL PREMI</td><td>{formatRupiah(sideResult.totalPayable)}</td></tr>
                  </tbody>
                </table>
              </div>
              </section>
            </div>

            <div className="quotation-letter__pdf-page quotation-letter__pdf-page--terms">
              <section className="quotation-letter__section quotation-letter__terms">
              <h3>SYARAT DAN KETENTUAN</h3>
              <h4>Wording Polis Standar Asuransi Kebakaran Indonesia</h4>
              <h5>Klausul</h5>
              <ul>
                <li>Klausul Penyakit Menular (LMA 5393).</li>
                <li>Klausul Pembayaran Premi 30 hari.</li>
                <li>Klausul Ketentuan Khusus Mengenai Kewajiban Tertanggung Menyampaikan Keterangan, Informasi Dan Data (Fakta Material) Dan Konsekuensi Pelanggarannya.</li>
                {term.totalDays > 366 ? <li>Klausul Polis Lebih dari Satu Tahun.</li> : null}
                <li>Klausul Bank.</li>
                <li>Klausul Pemberitahuan Kerugian (30 hari).</li>
                <li>Klausul Definisi Surat Permohonan Asuransi Umum (SPAU).</li>
                {hasFlood ? <li>Endorsemen Banjir, Angin Topan, Badai Dan Kerusakan Akibat Air (Kode: 4.3 A).</li> : null}
                {hasRsmd ? <li>Endorsemen Kerusuhan, Pemogokan, Dan Perbuatan Jahat (Kode: 4.1A / 2007).</li> : null}
                {hasRsmdcc ? <li>Endorsemen Kerusuhan, Pemogokan, Perbuatan Jahat, Dan Huru-Hara (Kode: 4.1B / 2007).</li> : null}
              </ul>

              <h5>Warranty dan Ketentuan Khusus</h5>
              <ul>
                <li>Tidak terjadi klaim sampai dengan Tanggal Pengikatan/Mulai Berlaku (mana yang paling akhir); jika terjadi klaim, maka ketentuan akan direvisi.</li>
                <li>Tertanggung wajib menjaga kebersihan area di lokasi pertanggungan selama masa periode pertanggungan.</li>
                <li>Objek pertanggungan tidak boleh dibiarkan kosong, tidak aktif, atau tidak diawasi selama masa pertanggungan. Bangunan/aset harus tetap digunakan dan tidak dalam kondisi terbengkalai (No Silent Risk).</li>
                <li>Objek pertanggungan agar dirinci per lokasi, tipe, jenis, dan unit harga ditegaskan dalam polis.</li>
                <li>Tidak ada perubahan okupasi selama periode pertanggungan.</li>
              </ul>

              <h5>Risiko Sendiri</h5>
              <ul>
                <li>Kebakaran: {isDwelling ? "Nil." : "5% dari nilai kerugian yang disetujui atau 0,1% dari total nilai pertanggungan untuk setiap risiko dan setiap lokasi, mana yang lebih besar."}</li>
                {hasFlood ? <li>Banjir: 10% dari jumlah ganti rugi yang disetujui.</li> : null}
                {hasEarthquake ? <li>Gempa: 2,5% dari Harga Pertanggungan Keseluruhan.</li> : null}
                {hasRsmd || hasRsmdcc ? <li>Kerusuhan / Kerusuhan dan Huru-Hara: 5% dari jumlah ganti rugi yang disetujui, minimum Rp5.000.000 setiap kejadian.</li> : null}
              </ul>
              </section>

              <p className="quotation-disclaimer">{UNDERWRITING_DISCLAIMER}</p>
              <div className="quotation-letter__signature"><span>Hormat kami,</span><strong>PT Asuransi Jasa Indonesia</strong></div>
            </div>

          </article>
        ) : null}
      </main>
      {isMapPickerOpen ? <RiskAddressMapPicker onClose={() => setIsMapPickerOpen(false)} onSelect={(address) => { update("riskAddress", address); setIsMapPickerOpen(false); }} /> : null}
      <footer className="site-footer"><span>© {new Date().getFullYear()} PT Asuransi Jasa Indonesia.</span><span>Kalkulator Premi Kebakaran KPR Danantara</span></footer>
    </div>
  );
}
